WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM payments), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN island_id >= 6 THEN 'LARGE' ELSE 'SMALL' END AS island_id_tier, APPROX_PERCENTILE(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, PERCENTILE_APPROX(is_new_session, ARRAY(0.25, 0.5, 0.75)) AS is_new_session_quartiles, COUNT(*) AS row_count, MAX(paid_at) AS ended_at, PERCENTILE_APPROX(island_id, 0.9) AS island_id_p90, MAX(is_new_session) AS max_is_new_session FROM islands GROUP BY island_id_tier HAVING PERCENTILE_APPROX(island_id, 0.9) < 0 ORDER BY row_count;
